    if lenient_issubclass(field.type_, sequence_types):
        return True
    return False


def get_dependant(
    *, path: str, call: Callable, name: str = None, security_scopes: List[str] = None
) -> Dependant:
    path_param_names = get_path_param_names(path)
    endpoint_signature = inspect.signature(call)
