                fixed_widths = [
                    _range.minimum if column.flexible else _range.maximum
                    for _range, column in zip(width_ranges, columns)
                ]
                flex_minimum = [
                    (column.width or 0) + padding_width
                    for column in columns
                    if column.flexible
